import { useReducer, Dispatch } from 'react';

export type LoaderState =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: string }
  | { status: 'error'; error: string };

export type LoaderAction =
  | { type: 'fetch' }
  | { type: 'resolved'; data: string }
  | { type: 'rejected'; error: string }
  | { type: 'reset' };

export function loaderReducer(state: LoaderState, action: LoaderAction): LoaderState {
  switch (action.type) {
    case 'fetch':
      if (state.status === 'loading') return state;
      return { status: 'loading' };
    case 'resolved':
      if (state.status !== 'loading') return state;
      return { status: 'success', data: action.data };
    case 'rejected':
      if (state.status !== 'loading') return state;
      return { status: 'error', error: action.error };
    case 'reset':
      return { status: 'idle' };
  }
}

export function useLoader(): readonly [LoaderState, Dispatch<LoaderAction>] {
  const [state, dispatch] = useReducer(loaderReducer, { status: 'idle' } as LoaderState);
  return [state, dispatch] as const;
}
